pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, address to, uint256 v) public {
        RecordingCallee rec = new RecordingCallee();
        address[] memory tos = new address[](1);
        tos[0] = address(rec);

        bool ok; try c.transfer(from, address(rec), tos, v) { ok = true; } catch { ok = false; }
        assertTrue(ok);

        assertTrue(rec.sawTransferFromSelector());
    }
}

contract RecordingCallee {
    bool private _sawTransferFrom;
    uint256 private _callCount;

    function transferFrom(address, address, uint256) external returns (bool) {
        _sawTransferFrom = true;
        _callCount++;
        return true;
    }

    fallback() external payable {
        _callCount++;
    }

    function sawTransferFromSelector() external view returns (bool) {
        return _sawTransferFrom;
    }

    function callCount() external view returns (uint256) {
        return _callCount;
    }
}
